const texto = $json.texto_ocr || '';
const capturar = (regex, grupo = 0) => {
  const resultado = texto.match(regex);
  return resultado ? resultado[grupo] : null;
};

return [{
  json: {
    numero_nota: capturar(/(?:NF|Nota Fiscal|Número|Numero)[:\s]*([0-9]{3,})/i, 1),
    fornecedor: capturar(/Fornecedor[:\s]*(.+)/i, 1)?.trim() || null,
    cnpj: capturar(/\d{2}\.\d{3}\.\d{3}\/\d{4}-\d{2}/),
    data_emissao: capturar(/\d{2}\/\d{2}\/\d{4}/),
    valor_total: capturar(/R\$\s?\d{1,3}(?:\.\d{3})*,\d{2}/),
    categoria: capturar(/Categoria[:\s]*(.+)/i, 1)?.trim() || 'Não classificado'
  }
}];

const obrigatorios = ['numero_nota', 'fornecedor', 'cnpj', 'data_emissao', 'valor_total'];
const campos_pendentes = obrigatorios.filter((campo) => !$json[campo]);

return [{
  json: {
    ...$json,
    status: campos_pendentes.length === 0 ? 'Processado' : 'Necessita revisão manual',
    campos_pendentes
  }
}];
